public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1) {
        throw new IllegalArgumentException("Day step must be a positive integer");
    }
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket must be a non-negative integer");
    }
    long day = timeBucket / 1000000;
    long hour = (timeBucket % 1000000) / 10000;
    long minute = (timeBucket % 10000) / 100;
    long second = timeBucket % 100;
    long compressedTimeBucket = day * 1000000 + hour * 10000 + minute * 100 + second;
    return compressedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  if (str == null) {
    throw new IllegalArgumentException("CharSequence cannot be null");
  }
  if (index < 0 || index >= str.length()) {
    throw new IndexOutOfBoundsException("Index out of bounds");
  }
  if (len < 0 || len > str.length() - index) {
    throw new IllegalArgumentException("Length out of bounds");
  }

  int size = 0;
  for (int i = index; i < index + len; i++) {
    char c = str.charAt(i);
    if (c <= 0x7F) {
      size += 1;
    } else if (c <= 0x7FF) {
      size += 2;
    } else if (Character.isHighSurrogate(c)) {
      size += 4;
      i++;
    } else {
      size += 3;
    }
  }

  return size;
}

