public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {

    // Check if the byte array is null
    if (byteArrayValue == null) {
        // If the byte array is null, put the specified number of null bytes into this byte vector
        for (int i = 0; i < byteLength; i++) {
            this.putByte((byte) 0);
        }
        return this;
    }

    // Check if the byte offset is valid
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Byte offset is out of bounds: " + byteOffset);
    }

    // Check if the byte length is valid
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("Byte length is out of bounds: " + byteLength);
    }

    // Put the byte array into this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        this.putByte(byteArrayValue[i]);
    }

    return this;
}

