public long readRawVarint64() throws IOException {
    long result = 0;
    int offset = 0;
    while (offset < 64) {
        byte b = readByte();
        result |= (long) (b & 0x7F) << offset;
        if ((b & 0x80) == 0) {
            return result;
        }
        offset += 7;
    }
    throw new IOException("Malformed varint");
}

