        throw new IndexOutOfBoundsException("The offset must be non-negative and less than the length of the byte array");
    }
    if (len < 0 || len > b.length - off) {
        throw new IndexOutOfBoundsException("The length must be non-negative and less than or equal to the length of the byte array minus the offset");
    }
    for (int i = off; i < off + len; i++) {
        write(b[i]);
    }
}

