public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
  // Calculate the midpoint of the box along the x axis
  double midpoint = box.getMinX() + (box.getWidth() / 2);

  // Create two new boxes with the same height and depth as the original box
  Box2D box1 = new Box2D(box.getMinX(), box.getMinY(), midpoint - box.getMinX(), box.getHeight());
  Box2D box2 = new Box2D(midpoint, box.getMinY(), box.getMaxX() - midpoint, box.getHeight());

  // Return a pair with the two resulting boxes
  return new Pair<>(box1, box2);
}

