            stackMapTableEntries.add(new LongStackMapFrameEntry((Long) type));
        } else if (type instanceof Double) {
            stackMapTableEntries.add(new DoubleStackMapFrameEntry((Double) type));
        } else if (type instanceof String) {
            stackMapTableEntries.add(new StringStackMapFrameEntry((String) type));
        } else if (type instanceof Class) {
