public final byte[] toByteArray() {
  // Check if the buffer is empty
  if (this.size() == 0) {
    return new byte[0];
  }

  // Create a new byte array with the total size of all the buffers
  byte[] result = new byte[this.size()];

  // Iterate over the buffers and copy their contents to the result array
  int offset = 0;
  for (ByteBuffer buffer : this.buffers) {
    int length = buffer.remaining();
    buffer.get(result, offset, length);
    offset += length;
  }

  return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    sb.append('\r');
                    i++;
                } else if (nextChar == 't') {
                    sb.append('\t');
                    i++;
                } else if (nextChar == 'b') {
                    sb.append('\b');
                    i++;
                } else if (nextChar == 'f') {
                    sb.append('\f');
                    i++;
                } else if (nextChar == '\\') {
                    sb.append('\\');
                    i++;
                } else if (nextChar == '\'') {
                    sb.append('\'');
                    i++;
                } else if (nextChar == '\"') {
                    sb.append('\"');
                    i++;
                } else {
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
                }
            } else {
                throw new Exception("Invalid escape sequence: \\");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

