public ByteVector putInt(final int intValue) {
    // Step 1: Check if the byte vector is large enough to hold the int value
    if (this.data.length < this.position + 4) {
        // If the byte vector is not large enough, create a new byte vector with a larger size
        byte[] newData = new byte[this.position + 4];
        // Copy the existing data to the new byte vector
        System.arraycopy(this.data, 0, newData, 0, this.position);
        this.data = newData;
    }

    // Step 2: Put the int value into the byte vector
    this.data[this.position++] = (byte) (intValue >>> 24);
    this.data[this.position++] = (byte) (intValue >>> 16);
    this.data[this.position++] = (byte) (intValue >>> 8);
    this.data[this.position++] = (byte) intValue;

    return this;
}

