    throw new IllegalArgumentException("Arrays must have at least " + count + " elements");
  }

  for (int i = 0; i < count; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }

  return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
  // Check if the nameStart is valid
  if (nameStart < 0 || nameStart >= buf.length()) {
    throw new IllegalArgumentException("Invalid nameStart: " + nameStart);
  }

  // Check if the buffer is empty
  if (buf.length() == 0) {
    return;
  }

  // Abbreviate the name
  int i = nameStart;
  while (i < buf.length() && !Character.isWhitespace(buf.charAt(i))) {
    buf.setCharAt(i, Character.toUpperCase(buf.charAt(i)));
    i++;
  }
}

